{
  "finding_id": "F-080",
  "binding_sha256": "62218fe3e8fa3d7231081e847ec4b297c2818dae3d7496f0086702085ddc9219",
  "decision": "release",
  "checks": [
    {
      "check_id": "source_support",
      "status": "pass",
      "reason": "Изображение непосредственно подтверждает три размера одной вертикальной цепи у шкафа ШАУВ-1-К6-ПЧ. Противоречие установлено по графике, без использования утверждений других замечаний.",
      "evidence": [
        {
          "type": "image",
          "block_id": "blk_d52bf811660e42b59acdce0038f9fbf0",
          "image_sha256": "42c7d8b05562c4c461752bf37d98233d9a519a4530360dd8f160494b4500ce95",
          "bbox_norm_xyxy": [0.429, 0.426, 0.718, 0.865],
          "observation": "На шкафу читается ШАУВ-1-К6-ПЧ. Размер 1400 соединяет уровни верха и низа шкафа; 1000 продолжает цепь от низа до верхней границы пола; внешний размер 1800 соединяет верх шкафа с тем же уровнем пола."
        }
      ]
    },
    {
      "check_id": "quantities_and_scope",
      "status": "pass",
      "reason": "1400 + 1000 = 2400 мм; разность с общим размером 1800 мм составляет 600 мм. Вывод ограничен показанным монтажным узлом и не превращает его размеры в универсальные требования.",
      "evidence": [
        {
          "type": "image",
          "block_id": "blk_d52bf811660e42b59acdce0038f9fbf0",
          "image_sha256": "42c7d8b05562c4c461752bf37d98233d9a519a4530360dd8f160494b4500ce95",
          "bbox_norm_xyxy": [0.429, 0.426, 0.51, 0.865],
          "observation": "У последовательных размеров 1400 и 1000 общий промежуточный уровень — низ шкафа. Крайние уровни совпадают с концами общего размера 1800."
        }
      ]
    },
    {
      "check_id": "original_clause_preservation",
      "status": "pass",
      "reason": "Сохранены все содержательные основания исходного замечания: принадлежность размеров одной цепи, значения, арифметическое расхождение, монтажная неоднозначность и необходимость согласования. Удалены повторения и историческая ссылка на F-036/G-102. Замечание остаётся видимым согласно publication_effect.",
      "evidence": [
        {
          "type": "image",
          "block_id": "blk_d52bf811660e42b59acdce0038f9fbf0",
          "image_sha256256": null,
          "image_sha256": "42c7d8b05562c4c461752bf37d98233d9a519a4530360dd8f160494b4500ce95",
          "bbox_norm_xyxy": [0.429, 0.426, 0.718, 0.865],
          "observation": "Графика подтверждает сохранённое исходное основание: несовместимые значения 1400, 1000 и 1800 между связанными уровнями установки одного шкафа."
        }
      ]
    },
    {
      "check_id": "uncertainty_and_consequences",
      "status": "pass",
      "reason": "Риск ограничен неоднозначностью проектной высоты при монтаже. Фактическая неправильная установка не утверждается; правильное значение не выбирается без основания. Решение предусматривает согласование габарита и высоты установки.",
      "evidence": [
        {
          "type": "image",
          "block_id": "blk_d52bf811660e42b59acdce0038f9fbf0",
          "image_sha256": "42c7d8b05562c4c461752bf37d98233d9a519a4530360dd8f160494b4500ce95",
          "bbox_norm_xyxy": [0.429, 0.426, 0.718, 0.865],
          "observation": "На монтажном изображении одновременно заданы несовместимые размеры; указания, какой из них имеет приоритет, в узле нет."
        }
      ]
    },
    {
      "check_id": "profile_and_norms",
      "status": "pass",
      "reason": "Размещение в technical_findings и существенная значимость обоснованы конкретным расхождением монтажной размерной цепи на 600 мм: выполнить все три указания одновременно невозможно. Это техническая несогласованность исходных монтажных данных. Нормативное нарушение не заявлено; norm и norm_quote оставлены null.",
      "evidence": [
        {
          "type": "image",
          "block_id": "blk_d52bf811660e42b59acdce0038f9fbf0",
          "image_sha256": "42c7d8b05562c4c461752bf37d98233d9a519a4530360dd8f160494b4500ce95",
          "bbox_norm_xyxy": [0.429, 0.426, 0.718, 0.865],
          "observation": "Противоречащие друг другу значения определяют габарит шкафа и его вертикальное положение относительно пола."
        }
      ]
    },
    {
      "check_id": "peer_overlap",
      "status": "pass",
      "reason": "Проверка представления: среди переданных текущих замечаний нет дубликата этой размерной цепи. Текущий F-036 посвящён обозначениям преобразователей; историческая ссылка на него обоснованно удалена. Другие замечания по листу 53 рассматривают кровельные опоры. Их утверждения не использованы как доказательства.",
      "evidence": []
    },
    {
      "check_id": "final_citations",
      "status": "pass",
      "reason": "Предложенное поле evidence содержит ссылки на приложенный графический блок с соответствующим хешем и областями, охватывающими шкаф, отдельные размеры и всю цепь. Эти ссылки поддерживают сохранённые технические утверждения. Лист 53 подтверждён метаданными; устаревшая ссылка на F-036 удалена.",
      "evidence": [
        {
          "type": "image",
          "block_id": "blk_d52bf811660e42b59acdce0038f9fbf0",
          "image_sha256": "42c7d8b05562c4c461752bf37d98233d9a519a4530360dd8f160494b4500ce95",
          "bbox_norm_xyxy": [0.429, 0.426, 0.718, 0.865],
          "observation": "Область заключительной ссылки proposed.evidence охватывает обозначение шкафа, все три вертикальных размера и их крайние уровни."
        },
        {
          "type": "metadata",
          "block_id": "blk_d52bf811660e42b59acdce0038f9fbf0",
          "quote": "Sheet: 53"
        }
      ]
    }
  ]
}
